mapper.insert:
INSERT INTO punch_source_config (
  tenant_id, source_system, config_name, api_base_url, api_key, api_secret, webhook_secret, enabled, config_json
) VALUES (
  #{tenantId}, #{in.sourceSystem}, #{in.connectorName}, #{in.apiBaseUrl}, #{in.apiKey}, #{in.apiSecret}, #{in.webhookSecret},
  CASE WHEN #{in.activeFlag} THEN 1 ELSE 0 END, #{configJson}
)

mapper.select:
SELECT e.id AS employee_id, e.employee_no, e.employee_name, w.workplace_name, d.department_name, m.source_system, m.external_employee_id, m.external_employee_no, m.status FROM employee_external_mapping m INNER JOIN employee e ON e.id = m.employee_id AND e.tenant_id = m.tenant_id LEFT JOIN workplace w ON w.id = e.workplace_id AND w.tenant_id = e.tenant_id LEFT JOIN department d ON d.id = e.department_id AND d.tenant_id = e.tenant_id WHERE m.tenant_id = #{tenantId}
AND m.source_system = #{query.sourceSystem}
AND ( e.employee_no LIKE CONCAT('%', #{query.keyword}, '%') OR e.employee_name LIKE CONCAT('%', #{query.keyword}, '%') OR m.external_employee_id LIKE CONCAT('%', #{query.keyword}, '%') OR m.external_employee_no LIKE CONCAT('%', #{query.keyword}, '%') )
ORDER BY e.employee_no ASC

SELECT s.id, s.connector_id, s.source_system, c.config_name AS connector_name, s.trigger_type, s.external_request_id, s.sync_status, s.success_count, s.failed_count, s.error_message, s.request_snapshot, s.result_snapshot, s.retry_flag, s.retry_count, s.created_at, s.updated_at FROM attendance_punch_sync_log s LEFT JOIN punch_source_config c ON c.id = s.connector_id AND c.tenant_id = s.tenant_id WHERE s.tenant_id = #{tenantId}
AND s.source_system = #{query.sourceSystem}
AND ( s.source_system LIKE CONCAT('%', #{query.keyword}, '%') OR c.config_name LIKE CONCAT('%', #{query.keyword}, '%') OR s.external_request_id LIKE CONCAT('%', #{query.keyword}, '%') )
ORDER BY s.created_at DESC, s.id DESC LIMIT 30

mapper.insert:
INSERT INTO attendance_punch_sync_log (
  tenant_id, connector_id, source_system, trigger_type, external_request_id, sync_status, success_count,
  failed_count, error_message, request_snapshot, result_snapshot, retry_flag, retry_count
) VALUES (
  #{tenantId}, #{connectorId}, #{sourceSystem}, #{triggerType}, #{externalRequestId}, #{syncStatus}, #{successCount},
  #{failedCount}, #{errorMessage}, #{requestSnapshot}, #{resultSnapshot},
  CASE WHEN #{retryFlag} THEN 1 ELSE 0 END, #{retryCount}
)
